def choose_move(observation):
    sx, sy = observation.get("self_position", (0, 0))
    ox, oy = observation.get("opponent_position", (0, 0))
    env = observation.get("environment_name", "resource_collection")

    def move_towards(target_x, target_y):
        dx = 0
        dy = 0
        if target_x > sx:
            dx = 1
        elif target_x < sx:
            dx = -1
        if target_y > sy:
            dy = 1
        elif target_y < sy:
            dy = -1
        return [dx, dy]

    # Defensive accessors
    resources = observation.get("resources") or []
    unclaimed = observation.get("unclaimed_cells") or []
    opponent_territory = observation.get("opponent_territory") or []
    # Geography
    grid_width = observation.get("grid_width")
    grid_height = observation.get("grid_height")
    # For 'pursuit_evasion' role
    role = observation.get("self_role", "pursuer")
    # Territory control
    targets = unclaimed or opponent_territory

    if env == "pursuit_evasion":
        if role == "pursuer":
            # Move towards opponent
            return move_towards(ox, oy)
        else:
            # Evasion: move away from opponent
            dx = 0
            dy = 0
            if ox > sx:
                dx = -1
            elif ox < sx:
                dx = 1
            if oy > sy:
                dy = -1
            elif oy < sy:
                dy = 1
            # If opponent on same cell, move randomly
            if dx == 0 and dy == 0:
                dx = 1 if ox <= sx else -1
                dy = 1 if oy <= sy else -1
            return [dx, dy]
    elif env == "territory_control":
        if not targets:
            # No available targets, stay put
            return [0, 0]
        target_cell = min(targets, key=lambda t: abs(t[0] - sx) + abs(t[1] - sy))
        return move_towards(target_cell[0], target_cell[1])
    elif env == "resource_collection":
        if not resources:
            # No resources, go towards opponent or stay
            if opponent_territory:
                target = min(opponent_territory, key=lambda t: abs(t[0] - sx) + abs(t[1] - sy))
                return move_towards(target[0], target[1])
            else:
                # No info, move randomly
                return [0, 0]
        target_cell = min(resources, key=lambda t: abs(t[0] - sx) + abs(t[1] - sy))
        return move_towards(target_cell[0], target_cell[1])
    else:
        # Default fallback
        return [0, 0]

